!function(t){function r(r){for(var p,e,i=r[0],o=r[1],u=r[2],c=0,g=[];c<i.length;c++)e=i[c],Object.prototype.hasOwnProperty.call(m,e)&&m[e]&&g.push(m[e][0]),m[e]=0;for(p in o)Object.prototype.hasOwnProperty.call(o,p)&&(t[p]=o[p]);for(s&&s(r);g.length;)g.shift()();return n.push.apply(n,u||[]),a()}function a(){for(var t,r=0;r<n.length;r++){for(var a,e=n[r],i=!0,o=1;o<e.length;o++)a=e[o],0!==m[a]&&(i=!1);i&&(n.splice(r--,1),t=p(p.s=e[0]))}return t}function p(r){if(e[r])return e[r].exports;var a=e[r]={i:r,l:!1,exports:{}};return t[r].call(a.exports,a,a.exports,p),a.l=!0,a.exports}var e={},m={7:0},n=[];p.m=t,p.c=e,p.d=function(t,r,a){p.o(t,r)||Object.defineProperty(t,r,{enumerable:!0,get:a})},p.r=function(t){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(t,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(t,"__esModule",{value:!0})},p.t=function(t,r){if(1&r&&(t=p(t)),8&r)return t;if(4&r&&"object"==typeof t&&t&&t.__esModule)return t;var a=Object.create(null);if(p.r(a),Object.defineProperty(a,"default",{enumerable:!0,value:t}),2&r&&"string"!=typeof t)for(var e in t)p.d(a,e,function(r){return t[r]}.bind(null,e));return a},p.n=function(t){var r=t&&t.__esModule?function(){return t.default}:function(){return t};return p.d(r,"a",r),r},p.o=function(t,r){return Object.prototype.hasOwnProperty.call(t,r)},p.p="";var i=window.webpackJsonp=window.webpackJsonp||[],o=i.push.bind(i);i.push=r,i=i.slice();for(var u=0;u<i.length;u++)r(i[u]);var s=o;n.push([26,0]),a()}({26:function(t,r,a){"use strict";a.r(r);var p=a(0);Object(p.a)("ru","army",a(27),a(1))},27:function(t){t.exports=JSON.parse('{"category":[{"name":"苏联","link":"ru_shortcut"},{"name":"陆战武器","link":"ru_army"},{"name":"坦克","link":"ru_army#ru_army_tank"}],"model":"T-37/T-38/T-40轻型两栖侦察坦克","description":"<h6>综述：</h6><p>T-37A、T-38和T-40都同属侦察坦克，为了能穿越雪地、泥泞与沼泽，并能渡过河流深入前线和敌后执行侦察任务，此类坦克不但加强了机动性和耐用性，更是加装泅水动力装置（螺旋浆和尾舵）和加装了浮力装置，并造成水密性，成为一种轻型的两栖坦克。</p><p>T-37是受英国的VCL水陆两栖坦克的启发，从1931年开始研制，T-38是在T-37基础上进行改造而成，而T-40则是T-37A与T-38的替代品。基于只作侦察用的想法，这类坦克的装甲与火力都薄弱，因此其作战价值大受影响，尽管后来的T-40加厚了装甲（此时已不能作两栖坦克用），但在苏联卫国战争初期，这些坦克在正面战斗中损失是极大的。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"{{text}}T-37A轻型两栖侦察坦克四视图{{image}}imgs/ru/army/ru_army_tankampt_11.jpg{{text}}1939年5月，在Nomohar地区，苏军第11坦克旅侦察营的一辆T-37A两栖坦克。{{image}}imgs/ru/army/ru_army_tankampt_12.jpg{{text}}1941年7-8月，东线苏联战场，苏军一辆不明单位的T-37A两栖坦克。{{image}}imgs/ru/army/ru_army_tankampt_13.jpg","description":"<h6>T-37A轻型两栖侦察坦克</h6><p>相对早期的坦克，T-37A坦克采用了改进的弹簧圈悬挂装置，单推进器履带和驾驶系统，车体进行了加固，履带钢板护挡包装了轻木浮桥以增加浮力，1935年车体将原铆接改作了整体焊接，终于解决了防水问题。</p><p>性能参数（仅供参考）：</p><p>车长：3.75m，车宽：2.07m，车高：1.82m，车重：3.2t；乘员2人；</p><p>最高车速：35km/h；最大行程185km；</p><p>装甲厚度：10mm；</p><p>武器配备：一挺7.62mm机枪。</p><span class=\'custom-document-caption text-secondary\'><strong>外形特点：</strong><ol><li>悬挂系统内有4个小口径负重轮，采用弹簧连接悬挂。</li><li>车体后尾部装有泅水用的螺旋浆和控制方向的尾舵。</li><li>炮塔安装车体右侧位置；只配备了一挺机枪。</li></ol></span><p>T-37A两栖坦克在1933-1936年间，该型坦克共生产了约1200辆。</p>","caption":""},{"image":"{{text}}T-38轻型两栖侦察坦克四视图{{image}}imgs/ru/army/ru_army_tankampt_21.jpg{{text}}1939年12月，芬兰地区，苏军第9集团军独立装甲营的一辆T-38两栖坦克。{{image}}imgs/ru/army/ru_army_tankampt_22.jpg{{text}}1942年1月，东线苏联战场，苏军西方面军一辆不明单位的T-38水陆两栖坦克。{{image}}imgs/ru/army/ru_army_tankampt_23.jpg","description":"<h6>T-38轻型两栖侦察坦克</h6><p>T-38坦克对T37A的车体进行了改进，使车身更矮，履带也加宽了，驾驶装置更容易操作，泅水的性能更提升了不少。</p><p>性能参数（仅供参考）：</p><p>车长：3.76m，车宽1.95m，车高1.62m；车重：约3.3t；乘员2人；</p><p>最高车速：40km/h；最大行程170km；</p><p>装甲厚度：10mm；</p><p>武器配备：一挺7.62mm机枪。</p><span class=\'custom-document-caption text-secondary\'><strong>外形特点：</strong><ol><li>悬挂系统与T-37基本相同。</li><li>车体后尾部装有泅水用的螺旋浆和控制方向的尾舵。</li><li>炮塔位置改在车体左侧，仍然只配备一挺机枪。</li></ol></span><p>T-38两栖坦克从1937-1939年，该型坦克共生产了约1300辆。</p>","caption":""},{"image":"{{text}}T-40轻型两栖侦察坦克四视图{{image}}imgs/ru/army/ru_army_tankampt_31.jpg{{text}}1942年1月，东线苏联战场，苏军西方面军一辆不明单位的T-40水陆两栖坦克。{{image}}imgs/ru/army/ru_army_tankampt_32.jpg{{text}}1942年春季，东线苏联战场，苏军西方面军一辆不明单位的T-40水陆两栖坦克。{{image}}imgs/ru/army/ru_army_tankampt_33.jpg","description":"<h6>T-40轻型两栖侦察坦克</h6><p>T-40坦克安装了内嵌式的车体浮箱，使坦克能渡过更宽、水流更急的河流。但后期的T-40坦克加装了防护装甲和一门20mm火炮后，由于重量的增加（接近T-38的2倍重量），致使其失去了两栖的功能。</p><p>性能参数（仅供参考）：</p><p>车长：4.43m，车宽：2.50m，车高：2.12m；车重：约6t；乘员2人；</p><p>最高车速：45km/h； 最大行程350km；</p><p>装甲厚度：13mm；</p><p>武器配备：前期1挺12.7mm机枪和1挺7.62mm机枪；后期1门20mm火炮和1挺7.62mm机枪。</p><span class=\'custom-document-caption text-secondary\'><strong>外形特点：</strong><ol><li>悬挂系统改用了4个大口径的负重轮。</li><li>车体两侧各装有一个箱式浮筒。</li><li>后期的炮塔改装了一门小口径火炮。</li></ol></span><p>该型坦克在1939年12月开始生产，但生产数量不详，后来由于全力生产T-60，则两栖坦克的生产就被放弃了。</p>","caption":""}],"part2title":"战场上的T-37/T-38/T-40轻型两栖侦察坦克","part2description":"<article><p>最初T-37和T-38在苏军的作战行动中，主要是担负坦克部队、机械化及炮兵部队的侦察任务，在1936年基辅军区的一次演习中，T-38坦克还被重型轰炸机空降到战线后方，获得了苏联第一批空降坦克之名；T-38和T-40都参加了1940年对芬兰的冬季战争和初期的卫国战争，然而由于装甲薄弱，连步兵的反坦克枪都能将它击穿，所以作战价值不大，但当时由于坦克的缺乏，而苏军指挥官双喜欢将其作常规坦克使用（特别是T-40加厚装甲和更换20mm炮后），结果在战斗中大量被击毁或被缴获，德军后来还将这些缴获的坦克作前线机场巡逻警卫用。</p></article>","part2content":[{"image":"imgs/ru/army/ru_army_tankampt_41.jpg","description":"1936年秋，一辆隶属白俄罗斯军区的T-37水陆两栖坦克正在过浮桥。","caption":""},{"image":"imgs/ru/army/ru_army_tankampt_42.jpg","description":"1940年9月，东线苏联战场，一队隶属于列宁格勒方面军独立轻型坦克营的T-38水陆两栖坦克正准备向德军涅瓦河集团军发起进攻，注意其车身炮塔上的两位战术编号。","caption":""},{"image":"imgs/ru/army/ru_army_tankampt_43.jpg","description":"1941年，正在渡河的苏军第10机械化军的T-38水陆两栖坦克。","caption":""},{"image":"imgs/ru/army/ru_army_tankampt_44.jpg","description":"1941年，一队苏军T-40水陆两栖坦克正在河中行进。","caption":""},{"image":"imgs/ru/army/ru_army_tankampt_45.jpg","description":"1942年冬季，东线苏联战场，隶属苏军加里宁方面军不明单位的一辆T-40水陆两栖坦克正停靠在路旁。","caption":""},{"image":"imgs/ru/army/ru_army_tankampt_46.jpg","description":"1942年1月，东线苏联战场，苏军两辆T-40水陆两栖坦克正树林中行进，出发执行侦察任务。","caption":""},{"image":"imgs/ru/army/ru_army_tankampt_47.jpg","description":"1941年，东线苏联战场，3辆被德军缴获的T-37水陆两栖坦克；一个德军士兵坐在前面的坦克上。","caption":""},{"image":"imgs/ru/army/ru_army_tankampt_48.jpg","description":"一辆德军缴获的苏军T-37两栖坦克，修好后被德军用来保护乌克兰境内的德军空军机场。","caption":""}]}')}});